import { Button } from '@refy-design/web';
import { Input } from '@refy-design/web';
import { Menu } from '@refy-design/web';
import { useState } from 'react';
const stack = { display: 'grid', gap: 'var(--space-4)', minWidth: 0 } as const;
function MenuExample() {
  const [open, setOpen] = useState(false),
    [name, setName] = useState('Content guide'),
    [draft, setDraft] = useState(name),
    [editing, setEditing] = useState(false),
    [archived, setArchived] = useState(false);
  return (
    <div style={stack}>
      <Menu
        open={open}
        onOpenChange={setOpen}
        entries={[
          {
            id: 'rename',
            label: 'Rename',
            onSelect: () => {
              setDraft(name);
              setEditing(true);
            },
          },
          {
            id: 'archive',
            label: archived ? 'Restore' : 'Archive',
            onSelect: () => setArchived(!archived),
          },
        ]}
      >
        <Button onClick={() => setOpen(!open)}>Actions ▾</Button>
      </Menu>
      <p>
        {name} · {archived ? 'Archived' : 'Available'}
      </p>
      {editing && (
        <form
          style={stack}
          onSubmit={(e) => {
            e.preventDefault();
            if (draft.trim()) {
              setName(draft.trim());
              setEditing(false);
            }
          }}
        >
          <Input
            label="Material name"
            required
            value={draft}
            onChange={(e) => setDraft(e.target.value)}
          />
          <Button type="submit">Save name</Button>
          <Button type="button" variant="ghost" onClick={() => setEditing(false)}>
            Cancel
          </Button>
        </form>
      )}
    </div>
  );
}
export function Example() {
  return <MenuExample />;
}

import { Button } from '@refy-design/web';
import { Menu } from '@refy-design/web';
import { useState } from 'react';
export function Example() {
  const [open, setOpen] = useState(true);
  return (
    <Menu
      open={open}
      onOpenChange={setOpen}
      ariaLabel="Available actions"
      entries={[
        { id: 'view', label: 'View' },
        { id: 'edit', label: 'Edit unavailable', disabled: true },
      ]}
    >
      <Button onClick={() => setOpen(!open)} aria-expanded={open}>
        Actions
      </Button>
    </Menu>
  );
}
